// Porous Bone - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// The relief already produces the real shading (normals + AO on the perturbed
// map()). Here the material stays a nearly uniform bone/porcelain white and only
// DEEPENS inside the holes, where the light does not reach.
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = shell (light), u_col2 = hole interior (warm dark).

float DENSITY   = 7.0 * E;   // slider E    // MUST match the displacement
float R_MIN     = 0.10;
float R_MAX     = 0.46;
float SIZE_BIAS = 2.2;
float FILL      = 0.82 * F;   // slider F
float RIM       = 0.120;
float GRAIN     = 0.10;   // micro speckle on the shell   [0.0 .. 0.25]
float FRESNEL   = 0.22;   // waxy sheen at grazing angles [0.0 .. 0.5]

// --- SAME Voronoi-of-random-radii field as the displacement, so the chromatic
//     darkening falls EXACTLY where the geometry is hollow.
vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);

float hole = 8.0;

for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 c = vi + g;

    vec3 o = fract(sin(vec3(
        dot(c, vec3(127.1, 311.7,  74.7)),
        dot(c, vec3(269.5, 183.3, 246.1)),
        dot(c, vec3(113.5, 271.9, 124.6)))) * 43758.5453);

    float rr = fract(sin(dot(c, vec3(419.2, 371.9, 668.5))) * 24634.6345);
    float ex = fract(sin(dot(c, vec3(157.3, 113.7, 271.1))) * 15731.7431);

    float rad = mix(R_MIN, R_MAX, pow(rr, SIZE_BIAS));
    rad *= step(1.0 - FILL, ex);

    hole = min(hole, length(g + o - vf) - rad);
}

hole /= DENSITY;

// 1 deep inside a hole, 0 on the outer shell.
float inHole = 1.0 - smoothstep(-0.030, RIM * 0.6, hole);

// --- micro-grain: fine speckle that keeps the white from looking plastic.
vec3 gp = pModel * 90.0;
vec3 gi = floor(gp);
vec3 gf = gp - gi;
vec3 gw = gf * gf * (3.0 - 2.0 * gf);

float g000 = fract(sin(dot(gi + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g100 = fract(sin(dot(gi + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g010 = fract(sin(dot(gi + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g110 = fract(sin(dot(gi + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g001 = fract(sin(dot(gi + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g101 = fract(sin(dot(gi + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g011 = fract(sin(dot(gi + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g111 = fract(sin(dot(gi + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

float gz0 = mix(mix(g000, g100, gw.x), mix(g010, g110, gw.x), gw.y);
float gz1 = mix(mix(g001, g101, gw.x), mix(g011, g111, gw.x), gw.y);
float grain = mix(gz0, gz1, gw.z) - 0.5;

// --- composition: shell color, darkened toward u_col2 inside the cavities.
vec3 col = ubuf.u_col1 * (1.0 + GRAIN * grain);
col = mix(col, ubuf.u_col2, inHole * 0.85);

// waxy sheen on the outer shell only (not inside the holes).
float fres = pow(1.0 - max(dot(n_model, viewDir_model), 0.0), 3.0);
col += ubuf.u_col1 * fres * FRESNEL * (1.0 - inHole);

textureCol = col;

