// Porous Bone - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Look: porous/coral shell perforated by holes of RANDOM size and position.
// Method: 3D Voronoi where EVERY cell has its own random radius (wide spread ->
// big and tiny holes mixed) + a random "skip" that leaves some cells solid.
// In scope: d_surf, p, pModel.  Convention: d_surf -= amp * field.
// GPU note: 27 samples inside map(); on low-end Mali/Adreno keep DENSITY low.

float DENSITY   = 7.0 * E;   // slider E    // hole density (cells per unit)   [4 .. 14]
float R_MIN     = 0.10;   // smallest hole radius            [0.05 .. 0.20]
float R_MAX     = 0.46;   // largest  hole radius            [0.30 .. 0.55]
float SIZE_BIAS = 2.2;    // >1 = many small, few big holes  [1.0 .. 4.0]
float FILL      = 0.82 * F;   // slider F   // fraction of cells that get a hole [0.5 .. 1.0]
float DEPTH     = 0.060;  // hole depth                      [0.03 .. 0.08]
float RIM       = 0.120;  // rim rounding (smooth lip)       [0.08 .. 0.20]

vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);

// hole = union of spheres of random radius -> keep the SMALLEST signed distance.
float hole = 8.0;

for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 c = vi + g;

    // 3 independent randoms per cell: position offset, radius, existence.
    vec3 o = fract(sin(vec3(
        dot(c, vec3(127.1, 311.7,  74.7)),
        dot(c, vec3(269.5, 183.3, 246.1)),
        dot(c, vec3(113.5, 271.9, 124.6)))) * 43758.5453);

    float rr = fract(sin(dot(c, vec3(419.2, 371.9, 668.5))) * 24634.6345);
    float ex = fract(sin(dot(c, vec3(157.3, 113.7, 271.1))) * 15731.7431);

    // biased radius: pow pushes the distribution toward the small end.
    float rad = mix(R_MIN, R_MAX, pow(rr, SIZE_BIAS));

    // cells above the FILL threshold stay solid -> irregular, non-uniform lattice.
    rad *= step(1.0 - FILL, ex);

    // signed distance to this cell's sphere, in cell units.
    float dSph = length(g + o - vf) - rad;
    hole = min(hole, dSph);
}

hole /= DENSITY;   // back to model units

// Carve: inside a sphere (hole < 0) push the surface inward, with a rounded lip
// so the edges look eroded rather than cut with a knife.
float carve = 1.0 - smoothstep(0.0, RIM, hole);   // 1 in the hole, 0 outside

d_surf += DEPTH * carve;

// Anti-punch-through / ANTI-WHITE-SPECKLE.
// The carve term makes d_surf a NON-Lipschitz field: near a rim its gradient is
// ~DEPTH/RIM, so a full-length step overshoots the shell, the ray lands on the
// inner wall and calcNormal (sampled across the rim) returns a garbage normal ->
// isolated white pixels in the holes. Keeping DEPTH/RIM low and slowing the
// march to 0.5 keeps the effective Lipschitz constant under 1.
d_surf *= 0.5;
